SCENE = "SC['3.12.05']=function(t,K){\n  var HD='CHAPTER 12 · EUCLID\\'S COMPASS',BY=['#C8102E','#E8B10E','#1F4E9C'],ORG='#C26A0A';\n  var RC={3:'#7BC043',6:'#1E7B34',8:'#8B5A2B'};\n  function rodW(x,y,n,u,op){var g=S('g',{opacity:op});S('rect',{x:x,y:y-15,width:n*u,height:30,rx:4,fill:RC[n],stroke:'rgba(0,0,0,.45)','stroke-width':2},g);S('text',{x:x+n*u/2,y:y+7,'text-anchor':'middle','font-size':20,'font-weight':800,fill:'#fff',text:String(n)},g);return g;}\n  function tri(V,op,cols,w){for(var i=0;i<3;i++){var a=V[i],b=V[(i+1)%3];S('line',{x1:a[0],y1:a[1],x2:b[0],y2:b[1],stroke:cols?cols[i]:NAVY,'stroke-width':w||9,'stroke-linecap':'round',opacity:op});}}\n  function ang(v,a,b){return ((Math.atan2(v[1]-a[1],a[0]-v[0])*180/Math.PI)+360)%360;}\n  function arc(V,i,op,col){var v=V[i],a=V[(i+2)%3],c=V[(i+1)%3],a1=ang(v,a),a2=ang(v,c),lo=Math.min(a1,a2),hi=Math.max(a1,a2);if(hi-lo>180){var tm=lo;lo=hi;hi=tm+360;}\n    var r=46,p=[v[0]+r*Math.cos(lo*Math.PI/180),v[1]-r*Math.sin(lo*Math.PI/180)],q=[v[0]+r*Math.cos(hi*Math.PI/180),v[1]-r*Math.sin(hi*Math.PI/180)];\n    S('path',{d:'M'+p[0]+' '+p[1]+' A'+r+' '+r+' 0 0 0 '+q[0]+' '+q[1],fill:'none',stroke:col||ORG,'stroke-width':6,opacity:op});}\n  if(t<K.names-0.3){head('','');owl(1000,380,150,t);book(t,0.1,'sb-byrne-defs.jpg','CHAPTER 12 · LESSON 5','Properties of Triangles','Alexandria, about 300 BC');return;}\n  if(t<K.sides-0.3){head(HD,'Euclid\\'s names for triangles');owl(null);var o=fade(t,K.names-0.3,K.sides-0.3);\n    pic('sb-byrne-defs.jpg',330,96,620,520,1+0.03*(t-K.names),.5,.45,o);return;}\n  var V=[[420,530],[860,530],[560,200]];\n  if(t<K.isos-0.3){var sd=t<K.angles-0.3;head(HD,sd?'Some names tell about the sides':'Others tell about the angles');owl(null);var o2=fade(t,K.sides-0.3,K.isos-0.3);\n    S('polygon',{points:V.map(function(p){return p.join(',');}).join(' '),fill:'#FBF6EA',opacity:o2});\n    if(sd){for(var i=0;i<3;i++){var a=V[i],b=V[(i+1)%3],k=ramp(t,K.sides+i*0.35,0.4);S('line',{x1:a[0],y1:a[1],x2:b[0],y2:b[1],stroke:k>0?BY[i]:'#C9CFDC','stroke-width':k>0?12:8,'stroke-linecap':'round',opacity:o2});}label(1060,300,'sides',o2*ramp(t,K.sides,0.4),NAVY,34);}\n    else{tri(V,o2,null,8);for(var j=0;j<3;j++)arc(V,j,o2*ramp(t,K.angles+j*0.35,0.4));label(1060,300,'angles',o2*ramp(t,K.angles,0.4),ORG,34);}\n    return;}\n  if(t<K.scal-0.3){head(HD,'Isosceles: equal legs');owl(null);var o3=fade(t,K.isos-0.3,K.scal-0.3),I=[[460,540],[820,540],[640,170]];\n    label(640,130,'ISOSCELES',o3,NAVY,46);tri(I,o3,null,8);\n    if(t>=K.legs-0.5){var lo=ramp(t,K.legs-0.5,0.5)*o3;S('line',{x1:I[0][0],y1:I[0][1],x2:I[2][0],y2:I[2][1],stroke:GREEN,'stroke-width':14,'stroke-linecap':'round',opacity:lo});S('line',{x1:I[1][0],y1:I[1][1],x2:I[2][0],y2:I[2][1],stroke:GREEN,'stroke-width':14,'stroke-linecap':'round',opacity:lo});label(1010,360,'equal legs',lo,GREEN,32);}\n    return;}\n  if(t<K.today-0.3){head(HD,'Scalene: uneven');owl(null);var o4=fade(t,K.scal-0.3,K.today-0.3),C=[[380,540],[900,540],[500,330]];\n    label(640,130,'SCALENE',o4,NAVY,46);tri(C,o4,BY,10);if(t>=K.uneven-0.4)label(1010,330,'no sides the same',ramp(t,K.uneven-0.4,0.4)*o4,GREEN,30);return;}\n  head(HD,'Sort triangles and give two names');owl(null);var o5=ramp(t,K.today-0.3,0.5),u=56;\n  rodW(300,380,8,u,o5);rodW(360,460,6,u,o5*ramp(t,K.today,0.5));rodW(460,540,3,u,o5*ramp(t,K.today+0.4,0.5));\n  if(t>=K.sort-0.3)label(980,300,'two names',ramp(t,K.sort-0.3,0.4)*o5,GREEN,32);\n};\n"
CUE = " '3.12.05':function(){return{names:wt(/^names$/,0),sides:wt(/^sides$/),angles:wt(/^angles$/),isos:wt(/^Isosceles$/),legs:wt(/^legs$/),scal:wt(/^Scalene$/),uneven:wt(/^uneven$/),today:wt(/^Today$/),sort:wt(/^sort$/)};},\n"
